macro.todo_analytics.cleanup_nulls.macro_sql:
{% macro cleanup_nulls(column_name) %}
    {% if execute %}
        -- Check if the table exists
        {% set table_exists_query %}
            SELECT COUNT(*)
            FROM information_schema.tables
            WHERE table_schema = '{{ this.schema }}'
              AND table_name = '{{ this.table }}'
        {% endset %}

        {% set table_exists_results = run_query(table_exists_query) %}
        {% set table_exists = table_exists_results.rows[0][0] > 0 %}

        -- Run the DELETE only if the table exists
        {% if table_exists %}
            DELETE FROM {{ this }}
            WHERE {{ column_name }} IS NULL;
        {% else %}
            {{ log("Skipping DELETE because the table does not exist.", info=True) }}
            select 1
        {% endif %}
    {% else %}
        -- Dry-run mode: Log the SQL
        {{ log("DELETE FROM " ~ this ~ " WHERE " ~ column_name ~ " IS NULL;", info=True) }}
    {% endif %}
{% endmacro %}

macro.todo_analytics.star_cte.macro_sql:
{%- macro star_cte(select_columns, cte_name = '', except=[]) -%}

    {%- set include_cols = [] -%}
    {%- set nsp = namespace(is_in_brackets = False) %} {# "Move the variable's scope to be global" #}

    {%- for col in select_columns.split(',') -%}
        {%- if ')' in col %} {# "Argments to functions shouldn't be treated as column names" #}
            {%- set nsp.is_in_brackets = False %}
        {%- elif '(' in col %}
            {%- set nsp.is_in_brackets = True %}
        {%- endif %}

        {%- set col_tidied = col.strip().split(' ') | last -%}

        {%- if col_tidied not in except and not nsp.is_in_brackets -%}
            {%- set _ = include_cols.append(col_tidied) -%}

        {%- endif -%}
    {%- endfor -%}

    {% for col in include_cols %}
        {% if cte_name | length > 0 %}
            {{- cte_name -}} .
        {%- endif -%}
        {{- col -}}
        {{- ", " if not loop.last }}
    {%- endfor -%}

{%- endmacro -%}

