macro.todo_analytics.delete_outdated_tab.macro_sql:
{% macro delete_outdated_tables(schema) %} 
  {% if (schema is not string and schema is not iterable) or schema is mapping or schema|length <= 0 %}
    {% do exceptions.raise_compiler_error('"schema" must be a string or a list') %}
  {% endif %}

  {% call statement('get_outdated_tables', fetch_result=True) %}
    select current.schema_name,
           current.ref_name,
           current.ref_type
    from (
      select schemaname as schema_name, 
             tablename  as ref_name, 
             'table'    as ref_type
      from pg_catalog.pg_tables pt 
      where schemaname in (
        {%- if schema is iterable and (var is not string and var is not mapping) -%}
          {%- for s in schema -%}
            '{{ s }}'{% if not loop.last %},{% endif %}
          {%- endfor -%}
        {%- elif schema is string -%}
          '{{ schema }}'
        {%- endif -%}
      )
      union all
      select schemaname as schema_name, 
             viewname   as ref_name, 
             'view'     as ref_type
      from pg_catalog.pg_views
        where schemaname in (
        {%- if schema is iterable and (var is not string and var is not mapping) -%}
          {%- for s in schema -%}
            '{{ s }}'{% if not loop.last %},{% endif %}
          {%- endfor -%}
        {%- elif schema is string -%}
          '{{ schema }}'
        {%- endif -%}
      )) as current
    left join (values
      {%- for node in graph.nodes.values() | selectattr("resource_type", "equalto", "model") | list
                    + graph.nodes.values() | selectattr("resource_type", "equalto", "seed")  | list %} 
        ('{{node.schema}}', '{{node.name}}'){% if not loop.last %},{% endif %}
      {%- endfor %}
    ) as desired (schema_name, ref_name) on desired.schema_name = current.schema_name
                                        and desired.ref_name    = current.ref_name
    where desired.ref_name is null
  {% endcall %}

  {%- for to_delete in load_result('get_outdated_tables')['data'] %} 
    {% call statement() -%}
      {% do log('dropping ' ~ to_delete[2] ~ ' "' ~ to_delete[0] ~ '.' ~ to_delete[1], info=true) %}
      drop {{ to_delete[2] }} if exists "{{ to_delete[0] }}"."{{ to_delete[1] }}" cascade;
    {%- endcall %}
  {%- endfor %}

{% endmacro %}

macro.todo_analytics.coalesce_defaults.macro_sql:
{% macro coalesce_defaults(
    table_name,
    seed = false
  ) %}
  {%- for col in adapter.get_columns_in_relation(table_name) %}
    {%- set default_value = 0 if col.data_type.lower() in ["integer","numeric","bigint"] 
    else '1900-01-01' if col.data_type.lower() in "date" 
    else 'default' if col.data_type.lower() in ["text","string"] 
    else '1900-01-01 00:00:00' if col.data_type.lower() in "timestamp without time zone" 
    else '1900-01-01 00:00.000+0000' if col.data_type.lower() in "timestamp" 
    else 'false' if col.data_type.lower() in "boolean" 
    else '0' if col.data_type.lower() in "numeric" 
    else '0.00' if col.data_type.lower() in ["double precision","float"] 
    else 'default' -%}

    {%- if seed == false %}
      COALESCE(
        "{{ col.name }}",
        '{{default_value}}' :: {{ col.data_type }}
      ) AS {{ col.name }}
    {%- endif %}

    {%- if seed == true -%}
      {% if loop.first %}
         distinct NULL AS {{ col.name }}
      {% endif %}

      {% if not loop.first %}
        '{{default_value}}' :: {{ col.data_type }} AS {{ col.name }}
      {% endif %}
    {% endif %}

    {{ ',' if not loop.last }}
  {%- endfor -%}
{% endmacro %}

